-- Ejecuta una sola vez en Supabase > SQL Editor. Si ya ejecutaste el SQL anterior de esta conversación, NO lo ejecutes de nuevo.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,nombre text,rol text not null default 'usuario' check(rol in('usuario','admin')),created_at timestamptz default now());
create table public.canales(id uuid primary key default gen_random_uuid(),nombre text not null,descripcion text,logo_url text,portada_url text,url_transmision text not null,tipo_transmision text default 'embed',categoria text,activo boolean default true,destacado boolean default false,orden integer default 0,created_at timestamptz default now());
create table public.emisoras(id uuid primary key default gen_random_uuid(),nombre text not null,descripcion text,logo_url text,url_transmision text not null,activo boolean default true,destacado boolean default false,orden integer default 0,created_at timestamptz default now());
create table public.noticias(id uuid primary key default gen_random_uuid(),titulo text not null,slug text unique not null,resumen text,contenido text,imagen_url text,video_url text,categoria text,autor text,publicada boolean default false,fecha_publicacion timestamptz,created_at timestamptz default now());
create table public.programas(id uuid primary key default gen_random_uuid(),nombre text not null,descripcion text,logo_url text,portada_url text,dia_semana text,hora_inicio time,hora_fin time,activo boolean default true,created_at timestamptz default now());
create table public.podcasts(id uuid primary key default gen_random_uuid(),titulo text not null,slug text unique,descripcion text,portada_url text,audio_url text,video_url text,publicado boolean default false,created_at timestamptz default now());
create table public.especiales(id uuid primary key default gen_random_uuid(),titulo text not null,slug text unique,descripcion text,contenido text,portada_url text,video_url text,publicado boolean default false,created_at timestamptz default now());
create table public.infantil(id uuid primary key default gen_random_uuid(),titulo text not null,descripcion text,portada_url text,video_url text,activo boolean default true,created_at timestamptz default now());
create table public.banners(id uuid primary key default gen_random_uuid(),titulo text,imagen_url text not null,enlace text,activo boolean default true,orden integer default 0,created_at timestamptz default now());
create or replace function public.es_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and rol='admin'); $$;
create or replace function public.crear_perfil() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,nombre) values(new.id,coalesce(new.raw_user_meta_data->>'nombre','')); return new; end; $$;
create trigger al_registrar_usuario after insert on auth.users for each row execute procedure public.crear_perfil();
do $$ declare t text; begin foreach t in array array['profiles','canales','emisoras','noticias','programas','podcasts','especiales','infantil','banners'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "Leer perfil propio" on public.profiles for select to authenticated using(id=(select auth.uid()) or public.es_admin());
create policy "Administrar perfiles" on public.profiles for update to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura canales" on public.canales for select to anon,authenticated using(activo=true or public.es_admin()); create policy "Admin canales" on public.canales for all to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura emisoras" on public.emisoras for select to anon,authenticated using(activo=true or public.es_admin()); create policy "Admin emisoras" on public.emisoras for all to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura noticias" on public.noticias for select to anon,authenticated using(publicada=true or public.es_admin()); create policy "Admin noticias" on public.noticias for all to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura programas" on public.programas for select to anon,authenticated using(activo=true or public.es_admin()); create policy "Admin programas" on public.programas for all to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura podcasts" on public.podcasts for select to anon,authenticated using(publicado=true or public.es_admin()); create policy "Admin podcasts" on public.podcasts for all to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura especiales" on public.especiales for select to anon,authenticated using(publicado=true or public.es_admin()); create policy "Admin especiales" on public.especiales for all to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura infantil" on public.infantil for select to anon,authenticated using(activo=true or public.es_admin()); create policy "Admin infantil" on public.infantil for all to authenticated using(public.es_admin()) with check(public.es_admin());
create policy "Lectura banners" on public.banners for select to anon,authenticated using(activo=true or public.es_admin()); create policy "Admin banners" on public.banners for all to authenticated using(public.es_admin()) with check(public.es_admin());
grant usage on schema public to anon,authenticated; grant select on public.canales,public.emisoras,public.noticias,public.programas,public.podcasts,public.especiales,public.infantil,public.banners to anon,authenticated; grant all on public.profiles,public.canales,public.emisoras,public.noticias,public.programas,public.podcasts,public.especiales,public.infantil,public.banners to authenticated;
